script:
frappe.ui.form.on("Sales Invoice", {

    refresh: function(frm) {
        apply_insurance_split(frm);
        lock_insurance_fields(frm);
    },

    patient: function(frm) {
        if (!frm.doc.patient) return;
        apply_insurance_split(frm);
    },

    grand_total: function(frm) {
        apply_insurance_split(frm);
    }
});

function lock_insurance_fields(frm) {
    ["rw_insurance_provider_display",
     "rw_insurance_coverage",
     "rw_insurance_amount",
     "rw_copay_amount"
    ].forEach(function(f) {
        frm.set_df_property(f, "read_only", 1);
    });
}

function apply_insurance_split(frm) {
    if (!frm.doc.patient) return;

    frappe.call({
        method: "frappe.client.get",
        args: { doctype: "Patient", name: frm.doc.patient },
        callback: function(r) {
            if (!r.message || !r.message.rw_insurance_provider) {
                // No insurance — patient pays full amount
                frm.set_value("rw_insurance_provider_display", "None / Cash");
                frm.set_value("rw_insurance_coverage", 0);
                frm.set_value("rw_insurance_amount", 0);
                frm.set_value("rw_copay_amount", frm.doc.grand_total || 0);
                frm.dashboard.set_headline_alert(
                    "No insurance on file — patient pays full amount",
                    "orange"
                );
                return;
            }

            var provider = r.message.rw_insurance_provider;

            frappe.call({
                method: "frappe.client.get",
                args: {
                    doctype: "Insurance Provider",
                    name: provider
                },
                callback: function(ir) {
                    if (!ir.message) return;

                    var coverage = ir.message.coverage_percentage || 0;
                    var total    = frm.doc.grand_total || 0;
                    var ins_amt  = parseFloat(
                        ((total * coverage) / 100).toFixed(0));
                    var copay    = total - ins_amt;

                    frm.set_value("rw_insurance_provider_display",
                        ir.message.provider_name);
                    frm.set_value("rw_insurance_coverage", coverage);
                    frm.set_value("rw_insurance_amount", ins_amt);
                    frm.set_value("rw_copay_amount", copay);

                    var color = copay === 0 ? "green" : "blue";
                    frm.dashboard.set_headline_alert(
                        "\uD83D\uDCB3 " + ir.message.provider_name +
                        " covers " + coverage + "% " +
                        "(RWF " + ins_amt.toLocaleString() + ") \u2014 " +
                        "Patient pays RWF " + copay.toLocaleString(),
                        color
                    );
                }
            });
        }
    });
}
